SELECT id 
FROM fms_prod_line 
WHERE prod_line_name = #{prodLineName} 
AND work_shop_id = #{departmentId}
LIMIT 1

SELECT id 
FROM fms_work_group 
WHERE work_group_name = #{teamName} 
AND prod_line_id = #{prodLineId}
LIMIT 1

SELECT COUNT(*) > 0 
FROM fms_position_archive 
WHERE id = #{departmentCode} 
AND region = #{companyCode} 
AND type = 'CJ'

SELECT COUNT(*) > 0 
FROM fms_prod_line 
WHERE id = #{prodLineCode} 
AND work_shop_id = #{departmentCode}

SELECT COUNT(*) > 0 
FROM fms_work_group 
WHERE id = #{teamCode} 
AND prod_line_id = #{prodLineCode}
